package dev.aura.player;

import android.content.Context;
import android.os.*;
import java.util.concurrent.*;

/** A dedicated USB volume domain; never writes Android's STREAM_MUSIC volume. */
final class UsbVolume {
    interface Access{default String identity(long expected)throws java.io.IOException{return "";}long generation();boolean connected();byte[] descriptors(long expected)throws java.io.IOException;void claim(long expected,int iface)throws java.io.IOException;int control(long expected,int type,int request,int value,int index,byte[] bytes)throws java.io.IOException;}
    static Access access=new Access(){public String identity(long expected)throws java.io.IOException{return UsbRoute.volumeIdentity(expected);}public long generation(){return UsbRoute.generation();}public boolean connected(){return UsbRoute.fd()>=0;}public byte[] descriptors(long expected)throws java.io.IOException{return UsbRoute.descriptors(expected);}public void claim(long expected,int iface)throws java.io.IOException{UsbRoute.claimControl(expected,iface);}public int control(long expected,int type,int request,int value,int index,byte[] bytes)throws java.io.IOException{return UsbRoute.control(expected,type,request,value,index,bytes);}};
    static void init(Context c){context=c.getApplicationContext();}
    record State(boolean hardware,boolean checking,int level,String message) {}
    static volatile State state=new State(false,false,100,"USB DAC를 연결해 주세요.");static volatile double softwareGain=1;
    private static final Handler main=new Handler(Looper.getMainLooper());private static final ExecutorService worker=Executors.newSingleThreadExecutor();private static UsbVolumeProtocol.Target target;private static UsbVolumeProtocol.Range range;private static long generation,probed=-1;private static boolean writing,scheduled;private static String hardwareKey="";private static int desired=100;private static Context context;private static Runnable listener=()->{};private static final Runnable send=()->{scheduled=false;submit();};
    static void listener(Runnable action){listener=action;}
    private static void changed(){listener.run();UsbVolumePopup.routeChanged();}
    static boolean direct(){return AudioSettings.current!=null&&AudioSettings.current.mode().equals("usb");}
    static boolean adjustable(){return direct()&&context!=null&&access.connected()&&!state.checking&&(state.hardware||!AudioSettings.current.perfect());}
    static void selected(Context c){init(c);generation=access.generation();probed=-1;writing=false;softwareGain=1;state=new State(false,true,100,"재생을 시작하면 DAC 볼륨을 확인합니다.");main.post(UsbVolume::changed);}
    static void ensure(Context c){main.post(()->{if(!direct()||!access.connected()||probed==access.generation())return;probed=access.generation();refresh(c);});}
    static String hardwareKey(String identity,UsbVolumeProtocol.Target target){if(identity==null||identity.isEmpty())return "";try{return "usbHardwareVolume."+Hex.encode(java.security.MessageDigest.getInstance("SHA-256").digest((identity+"|"+target.iface()+"|"+target.unit()+"|"+target.protocol()+"|"+target.channels()).getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    private static void rememberHardware(String key,UsbVolumeProtocol.Range value){if(context!=null&&!key.isEmpty())context.getSharedPreferences("playback",0).edit().putInt(key,value.current()).apply();}
    static void refresh(Context c){context=c.getApplicationContext();long expected=access.generation();Access connection=access;generation=expected;writing=false;target=null;range=null;hardwareKey="";softwareGain=1;state=new State(false,true,100,"DAC 볼륨 확인 중…");changed();worker.execute(()->{try{byte[] raw=connection.descriptors(expected);UsbVolumeProtocol.Target found=UsbVolumeProtocol.find(raw);connection.claim(expected,found.iface());UsbVolumeProtocol.Transfer transfer=(type,request,value,index,bytes)->connection.control(expected,type,request,value,index,bytes);UsbVolumeProtocol.Range levels=UsbVolumeProtocol.read(transfer,found);String key=hardwareKey(connection.identity(expected),found);boolean failed=false;var prefs=c.getSharedPreferences("playback",0);if(!key.isEmpty()&&prefs.contains(key)&&levels.current()!=prefs.getInt(key,levels.current())){try{levels=UsbVolumeProtocol.writeValue(transfer,found,levels,prefs.getInt(key,levels.current()));}catch(Exception restoreFailed){failed=true;try{levels=UsbVolumeProtocol.read(transfer,found);}catch(Exception unavailable){}}}UsbVolumeProtocol.Range ready=levels;boolean restorationFailed=failed;main.post(()->{if(generation!=expected||access!=connection||connection.generation()!=expected)return;target=found;range=ready;hardwareKey=key;desired=ready.level();if(!restorationFailed)rememberHardware(key,ready);state=new State(true,false,desired,restorationFailed?"이전 하드웨어 볼륨을 복원하지 못했습니다. 기기 볼륨을 확인해 주세요.":"DAC별 하드웨어 볼륨 기억 · 비트퍼펙트 유지");changed();});}catch(Exception unsupported){main.post(()->{if(generation!=expected||access!=connection||connection.generation()!=expected)return;desired=c.getSharedPreferences("playback",0).getInt("usbSoftwareVolume",100);state=new State(false,false,desired,"하드웨어 볼륨 미지원 · 비트퍼펙트를 끄면 앱 볼륨을 사용할 수 있습니다.");settingsChanged();});}});}
    static void settingsChanged(){softwareGain=direct()&&!state.hardware&&!AudioSettings.current.perfect()?gain(state.level):1;changed();}
    static double gain(int level){return level<=0?0:Math.pow(10,(Math.min(100,level)-100)*.6/20);}
    static void set(int level){if(!adjustable()){if(context!=null)android.widget.Toast.makeText(context,state.checking?"DAC 볼륨을 확인하고 있습니다.":"이 DAC에서는 비트퍼펙트를 끈 뒤 앱 볼륨을 조절해 주세요.",android.widget.Toast.LENGTH_SHORT).show();return;}desired=Math.max(0,Math.min(100,level));UsbVolumePopup.change(context,desired);if(state.hardware){if(!scheduled){scheduled=true;main.postDelayed(send,60);}}else{state=new State(false,false,desired,"AURA USB 앱 볼륨 · 신호에 볼륨 처리가 적용됩니다.");context.getSharedPreferences("playback",0).edit().putInt("usbSoftwareVolume",desired).apply();settingsChanged();}}
    static void adjust(int delta){set(desired+delta);}
    private static void submit(){if(writing)return;writing=true;long expected=generation;UsbVolumeProtocol.Target unit=target;UsbVolumeProtocol.Range limits=range;int wanted=desired;String key=hardwareKey;Access connection=access;if(unit==null||limits==null){writing=false;return;}worker.execute(()->{try{UsbVolumeProtocol.Range result=UsbVolumeProtocol.write((type,request,value,index,bytes)->connection.control(expected,type,request,value,index,bytes),unit,limits,wanted);main.post(()->{if(generation!=expected||access!=connection||connection.generation()!=expected)return;writing=false;range=result;rememberHardware(key,result);state=new State(true,false,result.level(),"DAC 하드웨어 볼륨 · 비트퍼펙트 유지");changed();if(desired!=wanted)submit();});}catch(Exception error){main.post(()->{if(generation!=expected)return;writing=false;state=new State(true,false,state.level,"DAC 볼륨 변경을 확인하지 못했습니다. 다시 시도해 주세요.");changed();});}});}
    static void disconnected(){hardwareKey="";generation=access.generation();probed=-1;writing=false;main.removeCallbacks(send);scheduled=false;softwareGain=1;target=null;range=null;state=new State(false,false,100,"USB DAC를 연결해 주세요.");main.post(UsbVolume::changed);}
}
